        {q:"這門課對 PNF 的定位是？", options:["取代任務訓練的整套療法","讓任務練習做得起來的工具，做到就撤手","只用於急性期","只用於上肢"], a:1, why:"〔本站轉譯〕PNF 是工具，不是療法：讓指引推薦的練習做得起來、做得對、做得夠量，接著盡快撤手。"}
