        {q:"最適合節律啟動的病人是？", options:["需要肌力訓練的運動員","動作啟動困難的帕金森病人","急性韌帶損傷","肌力 5 級者"], a:1, why:"節律啟動針對啟動困難、張力高與協調差。"},
        {q:"節律啟動做到主動階段時，患側出現張力升高、動作變亂，應？", options:["直接進到抗阻","退回前一階段（輔助主動或被動）","停止所有治療","加快節奏"], a:1, why:"每一階段都要平順才往下走，出現張力升高或動作變亂就退回前一階段。"}
