      practice:`<p>夥伴假裝「很僵硬、不知道要怎麼動」。你用上肢 D1 屈曲做節律啟動，從被動到抗阻各 5 次，全程數拍子。</p><p>再用坐站做一次：從被動帶著前傾抬臀 3 次，到輔助、主動，最後在骨盆給輕阻力 3 次。</p>`,
