          "同一肌群在<b>不改變接觸手</b>、<b>不停頓</b>的情況下，連續做：向心收縮（動出去）→ 穩定（等長維持）→ 離心收縮（慢慢被拉回）。",
          "適應症：動作協調不良、<b>離心控制不良</b>、主動關節活動度不足，或動作<b>中段缺少主動控制</b>。",
          "<b>從哪裡開始</b>：常從動作的<b>終端</b>開始（例如站直的位置），先讓病人在終點撐住，再進到離心段；肌力差或協調不足者，可以先從<b>等長</b>或<b>離心</b>開始，再加入向心。",
          "目的：訓練<b>動作控制</b>、離心肌力與功能性活動範圍，特別是「坐下」「蹲」「放東西」這類需要控制的動作。",
