      practice:`<p>夥伴坐姿做膝伸直：你給阻力讓他伸到 3/4、撐住 3 秒、再慢慢被你壓回，全程他要「頂著」。做 8 次，換邊。</p><p>再改成坐站：夥伴從站姿開始，你在他骨盆給輕阻力，請他「慢慢坐，數到 5 才碰到椅子」。</p>`,
