        why:"翻身與橋式是床上生活的基礎，也是四層控制中 Security 與 Linking 的主要練習：橋式先練骨盆穩得住，翻身則要把頭、軀幹、肩胛、骨盆連結起來。",
        look:["IPNFA 官方翻身示範：怎麼利用重力與等張組合","松田現翻身三支：上肢與下肢型態各怎麼帶動翻身","橋式的阻力給法：手放在哪裡、往哪個方向"]
