      practice:`<p>挑一個你最常對家屬或同事說的 PNF 宣稱（例如「練健側可以帶動患側」），用這一課的證據把它改寫成一句<b>不過度承諾</b>的版本，並附上一篇文獻。寫進你的教學投影片或衛教單。</p>`,
